update public.rc_articles set released_on = '2026-10-10' where slug = 'release-2026-10-17-sourcework-piece-formats' and kind = 'release_note';
update public.rc_articles set released_on = '2026-10-13' where slug = 'release-2026-10-22-sourcework-analyze' and kind = 'release_note';
