select private.rc_release_guide(
  p_slug => 'sourcework-workflow-overview',
  p_tool_key => 'transcription',
  p_title => 'Sourcework: from recordings to reporting',
  p_summary => 'How the tool fits together: projects, sources, excerpts and pieces, and the optional analysis steps.',
  p_screen_keys => array['sourcework.projects', 'sourcework.project', 'sourcework.sources'],
  p_sort_order => 1,
  p_version_note => 'Rewritten for the Notebook, the Review tab and the Analyze, Synthesis and Outline steps',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework takes recordings and documents from upload to a script. For an ordinary assignment you transcribe audio, pick your own actualities and write the piece by hand. The analysis steps, Analyze, Synthesis and Outline, are optional, and each one waits for your decision."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start with the task you have"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For a complete first assignment, follow "},{"type":"text","text":"From interview recording to radio script","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-interview-to-script"}}]},{"type":"text","text":". It goes from uploading a recording through checking the transcript, saving excerpts and writing a piece, with no research questions and no AI."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To work on one step, see "},{"type":"text","text":"Starting a project and adding sources","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-starting-a-project"}}]},{"type":"text","text":", "},{"type":"text","text":"Working with the transcript and creating excerpts","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-transcript-and-excerpts"}}]},{"type":"text","text":" or "},{"type":"text","text":"Building a piece from narration and excerpts","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-pieces"}}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What each thing is"}]},{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"source","marks":[{"type":"bold"}]},{"type":"text","text":" is an original recording or PDF. A "},{"type":"text","text":"transcript","marks":[{"type":"bold"}]},{"type":"text","text":" is derived text, and an "},{"type":"text","text":"excerpt","marks":[{"type":"bold"}]},{"type":"text","text":" is a stretch of a source saved for reuse: a time range of a recording, or a passage of a PDF. A "},{"type":"text","text":"project","marks":[{"type":"bold"}]},{"type":"text","text":" is the work for one story and refers to sources; the same source can be in more than one project without a second upload. A "},{"type":"text","text":"piece","marks":[{"type":"bold"}]},{"type":"text","text":" is a script built from narration and excerpts."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find and reuse what you already have"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Notebook","marks":[{"type":"link","attrs":{"href":"/sourcework?tab=notebook"}}]},{"type":"text","text":" on the Sourcework home lists every source and every excerpt, whichever project they are in, and its search box finds spoken words, passages and excerpts across all of them. See "},{"type":"text","text":"Browse the Notebook","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-browse-source-library"}}]},{"type":"text","text":" and "},{"type":"text","text":"Searching across projects and sources","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-search"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The optional steps, in order"}]},{"type":"paragraph","content":[{"type":"text","text":"A project's own Notebook tab shows where it stands and names the next step. "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":" reads a source and proposes findings and a few clips, which you decide on from the project's "},{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":" tab. "},{"type":"text","text":"Synthesis","marks":[{"type":"bold"}]},{"type":"text","text":" reads the accepted findings and says what they establish for each research question. "},{"type":"text","text":"Outline with AI","marks":[{"type":"bold"}]},{"type":"text","text":" plans a piece as beats, and "},{"type":"text","text":"Write from outline","marks":[{"type":"bold"}]},{"type":"text","text":" turns the beats into narration. See "},{"type":"text","text":"Analyzing a source","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-research"}}]},{"type":"text","text":", "},{"type":"text","text":"Synthesis","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-synthesis"}}]},{"type":"text","text":", "},{"type":"text","text":"Outline a piece","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-outline"}}]},{"type":"text","text":" and "},{"type":"text","text":"A project at a glance","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-project-overview"}}]},{"type":"text","text":". Each of these steps sends the project's material to an outside service; building by hand sends nothing."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Check the underlying material"}]},{"type":"paragraph","content":[{"type":"text","text":"Before anything airs, verify quotations, speaker identities, names, numbers and the context of each excerpt against the original recording. Neither the transcript nor a finding replaces editorial judgment. Apply WUWF's editorial and confidentiality requirements when handling sources."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-interview-to-script',
  p_tool_key => 'transcription',
  p_title => 'From interview recording to radio script',
  p_summary => 'Transcribe a recording, pick the actualities yourself and write the piece by hand, with no AI step.',
  p_screen_keys => array['sourcework.projects', 'sourcework.project', 'sourcework.pieces', 'sourcework.piece'],
  p_sort_order => 3,
  p_version_note => 'Brought into the repository and updated: Notebook, Find existing, the format under the length',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework can take a recorded interview all the way to a usable script without any of the analysis steps. This walkthrough covers transcription, excerpts you pick yourself, and the piece editor. Research questions, Analyze, Synthesis and Outline are optional."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Add the recording"}]},{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Sourcework","marks":[{"type":"link","attrs":{"href":"/sourcework"}}]},{"type":"text","text":" and select "},{"type":"text","text":"+ New project","marks":[{"type":"bold"}]},{"type":"text","text":" on the Projects tab. Name the project, then drop the recording onto the box or select "},{"type":"text","text":"Choose files","marks":[{"type":"bold"}]},{"type":"text","text":", or add it later. For a recording that is already in the "},{"type":"text","text":"Notebook","marks":[{"type":"link","attrs":{"href":"/sourcework?tab=notebook"}}]},{"type":"text","text":", open the project and use "},{"type":"text","text":"+ Add source","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"Find existing","marks":[{"type":"bold"}]},{"type":"text","text":", instead of uploading another copy. See "},{"type":"text","text":"Starting a project and adding sources","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-starting-a-project"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Check the transcript"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the source in the project's list to open it. When transcription finishes, listen while following the words, which move with the audio. Check names, figures, who is speaking and any wording you might quote against the recording, and name the speakers from the "},{"type":"text","text":"Speakers","marks":[{"type":"bold"}]},{"type":"text","text":" button. "},{"type":"text","text":"Find in this transcript","marks":[{"type":"bold"}]},{"type":"text","text":" locates a phrase so you can listen around it. See "},{"type":"text","text":"Working with the transcript and creating excerpts","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-transcript-and-excerpts"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Pick the excerpts yourself"}]},{"type":"paragraph","content":[{"type":"text","text":"Find a passage that gives the story something: a concrete detail, a telling phrase, a firsthand account. A clip should make sense on its own and have clean entry and exit points. Select its words in the transcript, keep or change the suggested title, and save it as an excerpt. Play it from its card, and use "},{"type":"text","text":"Trim","marks":[{"type":"bold"}]},{"type":"text","text":" to move its start or end to a word. Repeat for other passages. Nothing has to be analyzed first."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Build the script by hand"}]},{"type":"paragraph","content":[{"type":"text","text":"In the project, open "},{"type":"text","text":"Pieces","marks":[{"type":"bold"}]},{"type":"text","text":" and select "},{"type":"text","text":"+ New piece","marks":[{"type":"bold"}]},{"type":"text","text":". Write narration in a block, and use the "},{"type":"text","text":"+","marks":[{"type":"bold"}]},{"type":"text","text":" rows between blocks to add the project's excerpts in order. Reorder, swap or remove blocks as you revise; "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" on an excerpt block refines the cut in this piece without changing the saved excerpt. Pick a "},{"type":"text","text":"Format","marks":[{"type":"bold"}]},{"type":"text","text":" under the length if you want a target, and read the length as an estimate: narration is timed at 160 words a minute, so read it aloud. See "},{"type":"text","text":"Building a piece from narration and excerpts","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-pieces"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Prepare for production"}]},{"type":"paragraph","content":[{"type":"text","text":"Listen to each finished cut against the original audio, and verify attribution, wording, context and sequence. "},{"type":"text","text":"Copy as text","marks":[{"type":"bold"}]},{"type":"text","text":" copies the script, and "},{"type":"text","text":"Export excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" downloads the project's clips as one zip, each at an even level. The piece saves a version as you work; "},{"type":"text","text":"History","marks":[{"type":"bold"}]},{"type":"text","text":" restores an earlier one."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Optional next steps"}]},{"type":"paragraph","content":[{"type":"text","text":"From here you can "},{"type":"text","text":"search across projects and sources","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-search"}}]},{"type":"text","text":", have a source "},{"type":"text","text":"analyzed","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-research"}}]},{"type":"text","text":" for findings and clips to review, or let AI "},{"type":"text","text":"outline a piece","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-outline"}}]},{"type":"text","text":" from the findings you have accepted. They are additional ways of working, not prerequisites for a script."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-starting-a-project',
  p_tool_key => 'transcription',
  p_title => 'Starting a project and adding sources',
  p_summary => 'Name a project, then add recordings and PDFs now or later.',
  p_screen_keys => array['sourcework.projects'],
  p_sort_order => 5,
  p_version_note => 'Projects and Notebook tabs, the Pick up strip, progress in the list, Delete project in the ⋮ menu',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A project is the workspace for one story. It starts with a name; sources, which are recordings and PDFs, are added to it now or later."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create a project"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the Projects tab of the "},{"type":"text","text":"Sourcework home page","marks":[{"type":"link","attrs":{"href":"/sourcework"}}]},{"type":"text","text":", select "},{"type":"text","text":"+ New project","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Type a title and, if you like, notes: what the project is about and who set it up."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add sources now if you have them. Drag recordings or PDFs onto the box, or select "},{"type":"text","text":"Choose files","marks":[{"type":"bold"}]},{"type":"text","text":". Several at once is fine; each becomes its own source, titled from its file name. Rename any title before you upload."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Create project","marks":[{"type":"bold"}]},{"type":"text","text":", or "},{"type":"text","text":"Create project and upload","marks":[{"type":"bold"}]},{"type":"text","text":" with the number of files."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"While files upload"}]},{"type":"paragraph","content":[{"type":"text","text":"Files upload three at a time. One bar shows overall progress, with a line for each file in progress. A file that fails stays at the top with the reason and a "},{"type":"text","text":"Retry","marks":[{"type":"bold"}]},{"type":"text","text":", and the rest carry on. An upload is not resumable, so a retry starts that file over."}]},{"type":"paragraph","content":[{"type":"text","text":"Stop","marks":[{"type":"bold"}]},{"type":"text","text":" lets the files already uploading finish and leaves the rest waiting; "},{"type":"text","text":"Resume","marks":[{"type":"bold"}]},{"type":"text","text":" starts them again. Keep the page open until it finishes. When every file is uploaded you land on the project. If some failed, the project is still created, and you can open it and add the rest later."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"After the upload"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Processing continues in the background. The project's source list shows each source's status and a progress bar, and the page updates on its own when it is done."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audio and video get a transcript. A PDF's text is extracted automatically: a plain read of the file first, falling back to OCR only when that is not enough."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If processing fails, the source says why under its title. Open it for "},{"type":"text","text":"Retry","marks":[{"type":"bold"}]},{"type":"text","text":"; the file itself is already safely uploaded."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Sourcework home"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pick up where you left off","marks":[{"type":"bold"}]},{"type":"text","text":", at the top, shows up to three projects: ones with a source that failed or findings waiting for review first, then the most recently active."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Projects","marks":[{"type":"bold"}]},{"type":"text","text":" tab lists the most recently active projects first, 25 to a page. The filters show how many projects each holds: "},{"type":"text","text":"All","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Started by me","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Needs attention","marks":[{"type":"bold"}]},{"type":"text","text":" (a source failed, or findings are waiting for review) and "},{"type":"text","text":"No sources","marks":[{"type":"bold"}]},{"type":"text","text":". Each row shows a bar of the five steps done (Sources, Analyze, Review, Synthesis, Piece) with the step it is on, its sources, its excerpts, who started it, its last activity and its status. Select anywhere on a row to open the project."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Notebook","marks":[{"type":"bold"}]},{"type":"text","text":" tab holds every source and every excerpt, whichever project they are in. See "},{"type":"text","text":"Browse the Notebook","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-browse-source-library"}}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Deleting a project"}]},{"type":"paragraph","content":[{"type":"text","text":"Only the person who started a project can delete it: open the project and choose "},{"type":"text","text":"Delete project…","marks":[{"type":"bold"}]},{"type":"text","text":" from the ⋮ menu beside its title. It asks once more and names what will happen: sources that only this project uses are removed with their transcripts and excerpts, and sources that another project also uses stay in the Notebook. A long list shows five names and a count."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A project does not need a source. One without any shows "},{"type":"text","text":"No sources","marks":[{"type":"bold"}]},{"type":"text","text":" in the list, and opens with an "},{"type":"text","text":"Add the first source","marks":[{"type":"bold"}]},{"type":"text","text":" button."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anything outside the accepted audio, video and PDF types is refused before the upload starts, with a message naming what is accepted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The file goes straight from your browser to storage. A long recording can take a few minutes to upload."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once a source is uploaded, it can be used in more than one project with no re-upload. See "},{"type":"text","text":"Add another source to a project","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-reference-another-source"}}]},{"type":"text","text":"."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-reference-another-source',
  p_tool_key => 'transcription',
  p_title => 'Add another source to a project',
  p_summary => 'Upload more recordings or PDFs to a project, reuse one already in Sourcework, and move between a project''s sources.',
  p_screen_keys => array['sourcework.project'],
  p_sort_order => 10,
  p_version_note => 'The source switcher is gone: each source is its own screen, reached from the project''s list',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A project can draw on more than one recording or document. When the same interview matters to more than one story, add it to each project instead of uploading it again. Every project then shares one original and one transcript."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add a source"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the project. On its "},{"type":"text","text":"Notebook","marks":[{"type":"bold"}]},{"type":"text","text":" tab, "},{"type":"text","text":"+ Add source","marks":[{"type":"bold"}]},{"type":"text","text":" sits with the filters above the source list. A project with no sources shows "},{"type":"text","text":"Add the first source","marks":[{"type":"bold"}]},{"type":"text","text":" instead."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On "},{"type":"text","text":"Find existing","marks":[{"type":"bold"}]},{"type":"text","text":", search for the source by title and select "},{"type":"text","text":"Reference","marks":[{"type":"bold"}]},{"type":"text","text":". It is added right away, with no confirmation step."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On "},{"type":"text","text":"Upload new","marks":[{"type":"bold"}]},{"type":"text","text":", drag in recordings or PDFs that are not in Sourcework yet, or select "},{"type":"text","text":"Choose files","marks":[{"type":"bold"}]},{"type":"text","text":". They upload the same way as from a new project."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Move between sources"}]},{"type":"paragraph","content":[{"type":"text","text":"The project screen lists its sources, and each one opens as its own screen with the player, transcript and excerpts. The back link at the top of a source returns to the project, which is the way to its other sources. The link carries the project, so "},{"type":"text","text":"Remove from this project…","marks":[{"type":"bold"}]},{"type":"text","text":" in the source's ⋮ menu knows which project to take it out of. A source opened from the home Notebook instead gains a "},{"type":"text","text":"Projects","marks":[{"type":"bold"}]},{"type":"text","text":" tab listing every project that uses it."}]},{"type":"paragraph","content":[{"type":"text","text":"The project's Notebook also has an "},{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" section with every excerpt from every one of its sources, behind a search box that covers only this project, and a "},{"type":"text","text":"Data points","marks":[{"type":"bold"}]},{"type":"text","text":" section with the findings decided on across them."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Take a source out of a project"}]},{"type":"paragraph","content":[{"type":"text","text":"Remove from this project…","marks":[{"type":"bold"}]},{"type":"text","text":", in the ⋮ at the end of a source's row or in the source's own menu, detaches it. The recording, its transcript and its excerpts stay in the Notebook and in any other project that uses it. "},{"type":"text","text":"Delete source…","marks":[{"type":"bold"}]},{"type":"text","text":", on the source's own screen only, deletes it everywhere, with its transcript and every excerpt made from it, and asks you to confirm."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An excerpt belongs to the source it was made from, so it shows in every project that uses that source."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retrying a failed transcription retries that source alone."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PDF documents are added the same way as audio. They open in the document viewer instead of the player."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-transcript-and-excerpts',
  p_tool_key => 'transcription',
  p_title => 'Working with the transcript and creating excerpts',
  p_summary => 'Find your way in a transcript, name speakers, and save a stretch of it as an excerpt.',
  p_screen_keys => array['sourcework.source'],
  p_sort_order => 15,
  p_version_note => 'The source screen''s menu, tabs, player and panels as they are now',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A recording opens as its own screen: the player, the transcript and, beside it, a panel of this source's excerpts. Excerpts are short clips saved for reuse. On a phone the same screen is three tabs, "},{"type":"text","text":"Transcript","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Speakers","marks":[{"type":"bold"}]},{"type":"text","text":", with the player docked at the bottom."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find your way"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find in this transcript","marks":[{"type":"bold"}]},{"type":"text","text":" looks for a word or phrase from two characters on. Matching words are highlighted. Select the arrows, or press Enter, to step through the matches."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The marks under the progress bar show where your excerpts are; select one to open it. With many excerpts the marks merge into a shaded strip, and darker means more excerpts there. Select a stretch of the strip to zoom the progress bar in until the excerpts separate into their own marks, and select "},{"type":"text","text":"Show the whole recording","marks":[{"type":"bold"}]},{"type":"text","text":" to zoom back out."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The player steps back and forward five seconds, changes speed, and follows the transcript as it plays; "},{"type":"text","text":"Jump to playhead","marks":[{"type":"bold"}]},{"type":"text","text":" scrolls back to the line being played. Space plays and pauses, and the "},{"type":"text","text":"?","marks":[{"type":"bold"}]},{"type":"text","text":" button lists the other keyboard shortcuts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Speakers","marks":[{"type":"bold"}]},{"type":"text","text":" button names the speakers, with the first few names after it. It opens a list ordered by who spoke most. Type a name to rename a speaker, select "},{"type":"text","text":"Hear an example","marks":[{"type":"bold"}]},{"type":"text","text":", or tick "},{"type":"text","text":"Interviewer","marks":[{"type":"bold"}]},{"type":"text","text":" beside the person asking the questions, so Analyze leaves their words out. "},{"type":"text","text":"Add","marks":[{"type":"bold"}]},{"type":"text","text":" at the bottom adds a speaker the transcript missed. From seven speakers a find box and an "},{"type":"text","text":"Unnamed only","marks":[{"type":"bold"}]},{"type":"text","text":" switch appear."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the transcript split one person into two voices, select "},{"type":"text","text":"Merge…","marks":[{"type":"bold"}]},{"type":"text","text":" on the extra speaker and choose who it really was. All of its lines move to that speaker."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a line"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ at the end of any line for "},{"type":"text","text":"Edit text","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Make an excerpt from this line","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Change speaker…","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Merge with the next line","marks":[{"type":"bold"}]},{"type":"text","text":". Double-clicking the text, or pressing E on the current line, also starts an edit, and while editing you can split the line at the cursor. Choosing "},{"type":"text","text":"＋ New speaker…","marks":[{"type":"bold"}]},{"type":"text","text":" when changing a line's speaker names someone new. "},{"type":"text","text":"Copy transcript","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Download .txt","marks":[{"type":"bold"}]},{"type":"text","text":", above the transcript, take the whole text with you."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a source's details"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ beside the source's title and choose "},{"type":"text","text":"Edit details","marks":[{"type":"bold"}]},{"type":"text","text":". A card opens with the title and, for a recording, the date it was recorded. Select "},{"type":"text","text":"Save","marks":[{"type":"bold"}]},{"type":"text","text":" to keep the change; the source's search entries update with it. A PDF has a title only. The same menu has "},{"type":"text","text":"Rebuild search index","marks":[{"type":"bold"}]},{"type":"text","text":", for a source transcribed before search existed or after a round of corrections, and the two ways out: "},{"type":"text","text":"Remove from this project…","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Delete source…","marks":[{"type":"bold"}]},{"type":"text","text":", each saying what it does before you confirm."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create an excerpt"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Drag to select the stretch of text you want. On a phone, touch and hold a word, then drag."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"New excerpt","marks":[{"type":"bold"}]},{"type":"text","text":" bar opens at the bottom of the transcript with a title already filled in, and the time range beside it. The title starts as the first words you selected and, a moment later, is replaced by a short description of what the speaker says, if you haven't started typing. When you save, the excerpt is named in full: the project, then who is speaking, then your title, such as Hurricane Isaias_Chip Simmons_Second fatality from generator fumes. That is also the name of the file you download."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Change the title if you like, then press Enter or select "},{"type":"text","text":"Save excerpt","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Preview","marks":[{"type":"bold"}]},{"type":"text","text":" plays the exact range; Esc cancels."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Working with excerpts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The panel lists this source's excerpts. "},{"type":"text","text":"In order","marks":[{"type":"bold"}]},{"type":"text","text":" follows the recording and "},{"type":"text","text":"Newest","marks":[{"type":"bold"}]},{"type":"text","text":" puts the latest first. From nine excerpts a filter box appears, and twenty show at a time with "},{"type":"text","text":"Show more","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The round "},{"type":"text","text":"play button","marks":[{"type":"bold"}]},{"type":"text","text":" on a card plays that excerpt. While it plays the button turns into a pause button, so you can stop it from the card without going to the player. Playing another excerpt switches to that one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trim","marks":[{"type":"bold"}]},{"type":"text","text":" shows the clip's words. Tap a word to move the start or end there, or nudge them with the −250, −50, +50 and +250 buttons. "},{"type":"text","text":"Play as cut","marks":[{"type":"bold"}]},{"type":"text","text":" plays the result, and "},{"type":"text","text":"Done trimming","marks":[{"type":"bold"}]},{"type":"text","text":" closes it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Export WAV","marks":[{"type":"bold"}]},{"type":"text","text":" renders the clip to its own audio file; "},{"type":"text","text":"Download","marks":[{"type":"bold"}]},{"type":"text","text":" appears when it is ready, and the button then reads "},{"type":"text","text":"Re-export","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Show in transcript","marks":[{"type":"bold"}]},{"type":"text","text":" scrolls to the clip's words."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Level","marks":[{"type":"bold"}]},{"type":"text","text":" line on a card shows the volume change applied to that excerpt, such as +4.2 dB. Every excerpt is measured when you create or trim it, then played and exported at a fixed level of -18 LUFS, the level the team preps actualities at in Audition, followed by a hard limiter that holds peaks at -6 dBFS. One actuality no longer comes in much hotter or quieter than the last. The level is one volume setting for the whole excerpt, so a speaker who drops to a whisper stays that far below their own normal voice; only the peaks are limited. Select "},{"type":"text","text":"Original level","marks":[{"type":"bold"}]},{"type":"text","text":" to play and export an excerpt as recorded, for example when the quiet is the point, and "},{"type":"text","text":"Even out","marks":[{"type":"bold"}]},{"type":"text","text":" to go back. A card that says "},{"type":"text","text":"measuring…","marks":[{"type":"bold"}]},{"type":"text","text":" is still being measured and updates by itself in a few seconds. If it says the excerpt couldn't be measured, it plays and exports as recorded."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Export excerpts (zip)","marks":[{"type":"bold"}]},{"type":"text","text":", in the Excerpts section of the project's Notebook, exports every excerpt in the project at once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select a card's title to rename it. "},{"type":"text","text":"Delete","marks":[{"type":"bold"}]},{"type":"text","text":" asks you to confirm."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When the source is in a project"}]},{"type":"paragraph","content":[{"type":"text","text":"Opened from a project, the panel has a switch between "},{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Data points","marks":[{"type":"bold"}]},{"type":"text","text":": the findings and clips Analyze proposed for this source, underlined in the transcript where they are. See "},{"type":"text","text":"Analyzing a source","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-research"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A PDF source works the same way, but you select a stretch of the extracted text instead of a time range. Its screen has "},{"type":"text","text":"Document","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Text","marks":[{"type":"bold"}]},{"type":"text","text":" views and a search box for the document."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trimming a clip after it has been exported makes that export stale. Re-export before you rely on the download."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Line menus and the speaker list work on a tablet or phone too: nothing waits on hovering. Tapping an excerpt's words on a phone opens it in a sheet; see "},{"type":"text","text":"Play, trim and manage an excerpt on a phone","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-excerpt-sheet-on-a-phone"}}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Level is never applied to the recording itself, only to playback and to exports. Very quiet field tape can need a boost of 35 to 45 dB. Past 20 dB the card notes that the boost raises the background noise along with the voice. If a clip is stereo with the voice in one channel only, the voice is played and exported on both sides. Re-export after changing an excerpt's level, since an earlier export keeps the level it was made at."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-pieces',
  p_tool_key => 'transcription',
  p_title => 'Building a piece from narration and excerpts',
  p_summary => 'Write a wrap, voicer or feature block by block, or outline it from your findings, then edit by hand or with the assistant. Every version is kept.',
  p_screen_keys => array['sourcework.pieces', 'sourcework.piece'],
  p_sort_order => 18,
  p_version_note => 'The Start your piece panel, search in the Pieces list, and Delete piece',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece is a reader, voicer, wrap, spot or feature you build from your own narration and the project's excerpts. It starts blank. You can write it block by block, or let AI outline it from your accepted findings, write the outline out as narration, and then edit it by hand or with the assistant."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start a piece"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project, select "},{"type":"text","text":"Pieces","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"+ New piece","marks":[{"type":"bold"}]},{"type":"text","text":". The editor opens at once on an empty piece with its title ready to type, and a "},{"type":"text","text":"Start your piece","marks":[{"type":"bold"}]},{"type":"text","text":" panel offers "},{"type":"text","text":"+ Narration","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"+ Excerpt","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Outline with AI","marks":[{"type":"bold"}]},{"type":"text","text":". The Pieces list shows each piece's length, how it was made and when it last changed, with a search box once there are pieces."}]},{"type":"paragraph","content":[{"type":"text","text":"A format sets the piece's target length and gives you a guide to write by. Choose one, or change it, any time from "},{"type":"text","text":"Format","marks":[{"type":"bold"}]},{"type":"text","text":" under the length at the top of the piece, and "},{"type":"text","text":"Show guide","marks":[{"type":"bold"}]},{"type":"text","text":" shows its description. The guide is a reminder of what the format usually asks for; it doesn't stop you doing something else. Choosing a format doesn't change what you've written."}]},{"type":"paragraph","content":[{"type":"text","text":"The formats are Reader / Voicer (about 0:30 to 0:45, no recorded excerpts), Cut and Copy (0:45, one excerpt), Wrap (about 0:45 to 1:00, one or two), Super Spot (2:00, one to three) and Feature (4:00, two to six). The excerpt counts are a usual range, not a requirement: a strong piece can use fewer."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Outline and write it out (optional)"}]},{"type":"paragraph","content":[{"type":"text","text":"On an empty piece, choose "},{"type":"text","text":"Outline with AI","marks":[{"type":"bold"}]},{"type":"text","text":". It plans the story as beats, with your excerpts placed where they belong, from the findings you have accepted. A piece with beats shows "},{"type":"text","text":"Write from outline","marks":[{"type":"bold"}]},{"type":"text","text":", which turns each beat into narration in place. Both are versions you can undo, and nothing is written until you ask. "},{"type":"text","text":"Outline a piece","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-outline"}}]},{"type":"text","text":" has the details."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add narration and excerpts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Narration","marks":[{"type":"bold"}]},{"type":"text","text":". Write in a narration block. Press Enter at the end of a block to add another below it, and Shift+Enter for a new line. Backspace in an empty block removes it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":". Between every block, and before the first and after the last, there is a + row. Select it and choose "},{"type":"text","text":"Excerpt from this project…","marks":[{"type":"bold"}]},{"type":"text","text":" to search the project's audio excerpts by title, words, speaker or source. Arrow keys move through the results and Enter adds one. The same row adds a narration block or an outline beat."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An excerpt's words always come from the transcript for the clip you hear. They cannot be retyped in the piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a block"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ beside a block for "},{"type":"text","text":"Move up","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Move down","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Mark as anchor intro","marks":[{"type":"bold"}]},{"type":"text","text":" (on narration), "},{"type":"text","text":"Swap excerpt…","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" and removal. On a desktop you can also drag the ⋮⋮ handle to reorder."}]},{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"anchor intro","marks":[{"type":"bold"}]},{"type":"text","text":" is the lead-in the anchor reads before a reporter's recorded piece. It is shown as its own block and isn't counted in the piece's length, so a 0:53 wrap stays 0:53 whatever the intro adds. Reader, voicer and cut and copy copy is part of the piece and is timed with it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Trim a clip in place"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" on an excerpt block. The clip's words appear in their transcript context. Tap a word to move the nearer end of the clip there, or nudge the start and end with the −250, −50, +50 and +250 buttons. "},{"type":"text","text":"Play as cut","marks":[{"type":"bold"}]},{"type":"text","text":" plays what you have. The same panel shortens long pauses; see "},{"type":"text","text":"Trim a clip and shorten its pauses","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-piece-trim-and-pauses"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"By default a trim belongs to this piece only and the excerpt itself is unchanged. Choose "},{"type":"text","text":"Update the excerpt everywhere","marks":[{"type":"bold"}]},{"type":"text","text":" to change the excerpt itself; the panel says how many other pieces use it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Length"}]},{"type":"paragraph","content":[{"type":"text","text":"The length at the top adds up narration, estimated at 160 words a minute, and the clips' own running time, without any anchor intro. Choosing a format sets a target; select "},{"type":"text","text":"Change target","marks":[{"type":"bold"}]},{"type":"text","text":" to use a different one. The piece shows how far under or over it is."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ask the assistant"}]},{"type":"paragraph","content":[{"type":"text","text":"Open the assistant from "},{"type":"text","text":"Assistant","marks":[{"type":"bold"}]},{"type":"text","text":" at the top of the piece (on a phone, the bar at the bottom). It knows which piece you have open and says so at the top: “Working in: …”. Ask it to tighten a passage, move a quote, trim a clip, add a line, or outline the piece again. Anything you have typed is saved before your message goes."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It changes only what you ask, and says what it changed. Its reply lists the tools it used."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It places and swaps excerpts by id. It can't change what a speaker said, and the lengths it reports come from the same arithmetic as the screen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each block it changed is marked "},{"type":"text","text":"Edited by the assistant","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Added by the assistant","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Undo","marks":[{"type":"bold"}]},{"type":"text","text":" on the mark puts that block back. The marks stay until you next edit the piece yourself."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From a + row, "},{"type":"text","text":"Ask the assistant to write it","marks":[{"type":"bold"}]},{"type":"text","text":" opens the assistant with a request for narration at that spot, for you to finish and send."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Saving and history"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece saves itself a moment after you stop typing. Every save is a version, including each change the assistant makes and every outline or write-out."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History","marks":[{"type":"bold"}]},{"type":"text","text":" lists the versions with who saved each one, and whether it was you, an outline or a write-out, or the assistant. Restore saves an earlier version again as the newest, so nothing is lost."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If someone else saves the piece while you are editing, you are asked to reload instead of overwriting their work."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Take it with you, or delete it"}]},{"type":"paragraph","content":[{"type":"text","text":"Copy as text","marks":[{"type":"bold"}]},{"type":"text","text":" copies the narration and the quoted words, with each clip's length and the total running time. "},{"type":"text","text":"Export excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" downloads every excerpt in the project as one zip. "},{"type":"text","text":"Delete piece…","marks":[{"type":"bold"}]},{"type":"text","text":", in the ⋮ at the top of the piece, removes the piece and its history after a confirmation; the project's excerpts are not affected."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only audio and video excerpts can go in a piece. Document excerpts have no sound."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If an excerpt is deleted after it was used, its block says so and can be swapped or removed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything on a piece works on a phone: menus and the + picker open as sheets, and Move up and Move down replace dragging."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Outlining, writing out and the assistant send the piece's material (accepted findings and the excerpts' words) to an outside service, as analysis does. Building a piece by hand doesn't."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Pieces list says how each piece was made: Written by hand, or the format it was written from, then edited."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-research',
  p_tool_key => 'transcription',
  p_title => 'Analyzing a source',
  p_summary => 'Analyze a source for the findings that add to what the project knows and a few clips worth hearing, then decide on them on the Review tab or beside the transcript.',
  p_screen_keys => array['sourcework.setup', 'sourcework.source', 'sourcework.project'],
  p_sort_order => 19,
  p_version_note => 'Analyze from the Notebook tab, and the project''s Review tab',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Analyze reads one source and tells you what in it matters: the few findings that add to what the project already knows, and a few passages that might work as audio. Everything it suggests waits for your decision, and nothing is quoted or used until you accept it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Analyze a source"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the project's "},{"type":"text","text":"Notebook","marks":[{"type":"bold"}]},{"type":"text","text":" tab, choose "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":": the next-step panel's button when sources are ready, or the one beside "},{"type":"text","text":"+ Add source","marks":[{"type":"bold"}]},{"type":"text","text":" above the source list. Each source is read on its own, up to three at a time, and a panel under the tabs shows progress. You can leave the page while it runs, as long as the browser tab stays open. A source that is still transcribing can be analyzed once it finishes, and "},{"type":"text","text":"Not analyzed","marks":[{"type":"bold"}]},{"type":"text","text":" under Show lists the ones still to do."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From a source, choose "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Analyze again","marks":[{"type":"bold"}]},{"type":"text","text":" under the Data points panel."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A research question is not required. With one, the model looks for what bears on it; without one, it looks for what a reporter would need to know, check or cite. Questions on the Setup tab sharpen the result, and fewer, more specific questions work better than a list of topics."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What you get"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Findings","marks":[{"type":"bold"}]},{"type":"text","text":": a short paraphrase with the passages it rests on, who said it, and one line on why it matters. The model is shown what the project has already accepted, so it adds to, sharpens or contradicts it instead of repeating it. Often it will find little in a source that repeats the others, and that is the intended result."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clips to review","marks":[{"type":"bold"}]},{"type":"text","text":": a few passages that might work on the air. Play one, trim it, then accept it into an ordinary excerpt or reject it. Often there are none. See "},{"type":"text","text":"Clips to review","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-suggested-quotes"}}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pages consulted","marks":[{"type":"bold"}]},{"type":"text","text":": the model can search the web when it needs context to read a source, such as an unfamiliar place, term or claim. The pages it relied on are listed on the Setup tab and under "},{"type":"text","text":"Pages the model looked up","marks":[{"type":"bold"}]},{"type":"text","text":" on the Review tab, and a search never uses an interviewee's name. They inform the model's reading and never count as evidence."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Set up the project"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project and select "},{"type":"text","text":"Setup","marks":[{"type":"bold"}]},{"type":"text","text":", at the right of the tabs. Where the project stands is the row of steps on the Notebook tab, above the sources, not repeated here."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add the questions you are trying to answer. The ⋮ beside a question moves it up or down, or archives it. Archived questions keep their findings and can be restored."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dismiss a page that is wrong or irrelevant and the model stops being shown it."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Say who the interviewer is"}]},{"type":"paragraph","content":[{"type":"text","text":"On a source, open the speakers menu and tick "},{"type":"text","text":"Interviewer","marks":[{"type":"bold"}]},{"type":"text","text":" beside the person asking the questions. What an interviewer says is not treated as a finding or a clip."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Decide on the project's Review tab"}]},{"type":"paragraph","content":[{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":", the tab with the count of findings and clips waiting, lists everything Analyze left waiting from every source, grouped by source. Play a finding's passage or a clip in place, or "},{"type":"text","text":"Open in source","marks":[{"type":"bold"}]},{"type":"text","text":" to read it beside the transcript. On a finding, "},{"type":"text","text":"Accept","marks":[{"type":"bold"}]},{"type":"text","text":" keeps it, "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" rewords the claim and accepts it, and "},{"type":"text","text":"Reject","marks":[{"type":"bold"}]},{"type":"text","text":" hides it; on a clip, Play, "},{"type":"text","text":"Accept","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Trim","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Reject","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Accept all","marks":[{"type":"bold"}]},{"type":"text","text":" for findings and for clips accepts everything waiting at once, after a confirmation. Nothing is deleted by deciding: an accepted finding offers "},{"type":"text","text":"Undo","marks":[{"type":"bold"}]},{"type":"text","text":", and a rejected one "},{"type":"text","text":"Put back for review","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review findings in the source"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a source from its project and switch the panel beside the transcript from Excerpts to "},{"type":"text","text":"Data points","marks":[{"type":"bold"}]},{"type":"text","text":". Each finding is underlined in lime where it is in the transcript. A dashed card and dashed underline are suggestions you have not reviewed yet. The chips show "},{"type":"text","text":"To review","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"All","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Rejected","marks":[{"type":"bold"}]},{"type":"text","text":", and the same Accept, Edit, Reject and Play buttons are on each card. Analyze again later: accepted and rejected findings and clips are kept, and only suggestions you have not reviewed are replaced."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A finding is a paraphrase. To use the speaker's own words, accept a clip or make an excerpt."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The findings you have decided on are listed under "},{"type":"text","text":"Data points","marks":[{"type":"bold"}]},{"type":"text","text":" in the project's Notebook, filtered Accepted, Rejected or Both, each linking to its source."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interview audio and text are sent to an outside service to be read, as they are for transcription."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything here works on a phone: the Excerpts tab holds the switch, and the player stays docked at the bottom."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-suggested-quotes',
  p_tool_key => 'transcription',
  p_title => 'Clips to review',
  p_summary => 'Play, trim, accept or reject the clips Analyze proposed from a source.',
  p_screen_keys => array['sourcework.project', 'sourcework.source'],
  p_sort_order => 23,
  p_version_note => 'Rewritten for Analyze''s clips; themes and tiers are gone',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A clip is a literal cut of a recording that Analyze thought might work on air, as against a finding, which is a paraphrase. Nothing becomes an excerpt until you accept it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Where clips are"}]},{"type":"paragraph","content":[{"type":"text","text":"Analyzing a source proposes up to five clips. They appear on the project's "},{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":" tab, grouped with that source's findings, and on the source's own page under "},{"type":"text","text":"Clips to review","marks":[{"type":"bold"}]},{"type":"text","text":", above the findings in the Data points panel. The section is absent when none is waiting; often there are none."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Decide on each clip"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each card shows who says it, the words, its length and why it works."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Play","marks":[{"type":"bold"}]},{"type":"text","text":" plays the clip as it will cut, from the original audio. Check the words as you listen: the transcript is itself a machine reading of the audio."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accept","marks":[{"type":"bold"}]},{"type":"text","text":" saves the clip as an ordinary excerpt on its source. It then appears in the source's excerpts, in the project's Excerpts section and in the piece editor's excerpt picker."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trim","marks":[{"type":"bold"}]},{"type":"text","text":" opens the start and end with the −250, −50, +50 and +250 buttons; "},{"type":"text","text":"Back to the suggested cut","marks":[{"type":"bold"}]},{"type":"text","text":" undoes them. Play again to hear the new cut, then Accept. The words are read again from the transcript for the range you accept."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reject","marks":[{"type":"bold"}]},{"type":"text","text":" hides the clip. It is kept, so the same stretch is not suggested again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the Review tab, "},{"type":"text","text":"Accept all N clips","marks":[{"type":"bold"}]},{"type":"text","text":" accepts every waiting clip at the range proposed, after a confirmation."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clips are only ever taken from the speaker's own words, one speaker at a time, at sentence edges, between 1.5 and 60 seconds."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything here works on a phone: cards stack, and the buttons are larger."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-research-prompts',
  p_tool_key => 'transcription',
  p_title => 'Maintaining the prompts',
  p_summary => 'For editors: the Analyze, Synthesis, Outline and Writing guides the model works from. Edit, publish and roll back.',
  p_screen_keys => array['sourcework.editors'],
  p_sort_order => 20,
  p_version_note => 'Reached from the Setup tab; the Writing guide',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Editors maintain the wording the model works from. You need the Editor role on Sourcework, which an administrator grants on the user's access screen; with it, a "},{"type":"text","text":"Setup","marks":[{"type":"bold"}]},{"type":"text","text":" tab appears at the right of the Sourcework tabs, with "},{"type":"text","text":"Prompts","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Piece formats","marks":[{"type":"bold"}]},{"type":"text","text":" under it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a prompt"}]},{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Setup","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"Prompts","marks":[{"type":"bold"}]},{"type":"text","text":". Choose a guide on the left (on a phone, from the list at the top): the "},{"type":"text","text":"Analyze guide","marks":[{"type":"bold"}]},{"type":"text","text":" decides what makes a finding worth keeping and a clip worth offering; the "},{"type":"text","text":"Synthesis guide","marks":[{"type":"bold"}]},{"type":"text","text":" how the accepted findings are weighed against the research questions; the "},{"type":"text","text":"Outline guide","marks":[{"type":"bold"}]},{"type":"text","text":" what makes a good outline and which clips earn a place in it; and the "},{"type":"text","text":"Writing guide","marks":[{"type":"bold"}]},{"type":"text","text":" the house style of the narration Write from outline produces, such as the tense of attribution. Edit the text and it saves itself as a draft only you can see. The shape of the answer is fixed by the code, and "},{"type":"text","text":"What the model is given and returns","marks":[{"type":"bold"}]},{"type":"text","text":" shows both. "},{"type":"text","text":"Discard draft","marks":[{"type":"bold"}]},{"type":"text","text":" goes back to the live text."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish and roll back"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Publish","marks":[{"type":"bold"}]},{"type":"text","text":" asks for a one-line note about what changed, then makes the draft the live version for every project's next run."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History","marks":[{"type":"bold"}]},{"type":"text","text":" lists earlier versions with their notes and, for the Analyze guide, the share of its findings people accepted. "},{"type":"text","text":"Edit from this version","marks":[{"type":"bold"}]},{"type":"text","text":" starts a draft from it, and "},{"type":"text","text":"Make live again","marks":[{"type":"bold"}]},{"type":"text","text":" moves an earlier version back into use. Nothing is deleted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Until something is published, a prompt runs on its built-in text."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-piece-formats',
  p_tool_key => 'transcription',
  p_title => 'Maintaining piece formats',
  p_summary => 'For editors: the length, actualities, description and style a piece format asks for. Edit, try a draft on a project, publish and roll back.',
  p_screen_keys => array['sourcework.formats'],
  p_sort_order => 21,
  p_version_note => 'Reached from the Setup tab',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece format is the shape and wording an outline, and writing the outline out, follow: its length, how many actualities it usually uses, a free-text description and style, and whether an anchor leads in. These are guardrails: the model decides the beats and chooses the actualities freely from the material, so every story can take its own shape. Editors maintain formats; you need the Editor role on Sourcework, which an administrator grants on the user's access screen."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a format"}]},{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Setup","marks":[{"type":"bold"}]},{"type":"text","text":", at the right of the Sourcework tabs, then "},{"type":"text","text":"Piece formats","marks":[{"type":"bold"}]},{"type":"text","text":". Pick a format on the left (on a phone, from the list at the top). Your changes save themselves as a draft only you can see, and "},{"type":"text","text":"Rename","marks":[{"type":"bold"}]},{"type":"text","text":" changes its name everywhere."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Length","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Plus or minus","marks":[{"type":"bold"}]},{"type":"text","text":": the length the piece should run and the range that counts as on target, such as 0:53 within 0:08, which is 0:45 to 1:01."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Usual actualities","marks":[{"type":"bold"}]},{"type":"text","text":": the fewest and most clips the piece usually uses. It is a guide, not a quota: an outline may use fewer, and only going over the most is flagged in a trial."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Description and style","marks":[{"type":"bold"}]},{"type":"text","text":": what the piece does and how it sounds, such as who reads it and what a listener should come away with. Write placeholders the reporter fills in, such as [REPORTER NAME], in square brackets. Don't lay out its blocks or their order: the model decides how many beats the story needs and where the actualities go. Tick "},{"type":"text","text":"An anchor may read a lead-in first","marks":[{"type":"bold"}]},{"type":"text","text":" for formats where the anchor can introduce a reporter's recorded piece. It is always optional, since a piece the anchor reads itself has none, and it isn't counted in the length."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The model writes beats, and narration when an outline is written out; actualities are always the project's own excerpts. A format can't change that, and it can't make the model type out a quote."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Try a draft"}]},{"type":"paragraph","content":[{"type":"text","text":"Try this draft","marks":[{"type":"bold"}]},{"type":"text","text":" outlines a piece from one project's accepted findings and excerpts with your draft and with the live version, and shows the two side by side with how many beats and actualities each used and how much clip time. Add a direction if you want to test one. Nothing is added to the project, and results are kept for 14 days under "},{"type":"text","text":"Recent trials","marks":[{"type":"bold"}]},{"type":"text","text":", visible only to you."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish and roll back"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Publish","marks":[{"type":"bold"}]},{"type":"text","text":" asks for a one-line note about what changed, then makes the draft the live version. Reporters' next outlines follow it; pieces already outlined keep the version they followed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History","marks":[{"type":"bold"}]},{"type":"text","text":" lists every version with its note and how many pieces it made. "},{"type":"text","text":"Edit from this version","marks":[{"type":"bold"}]},{"type":"text","text":" starts a draft from it, and "},{"type":"text","text":"Make live again","marks":[{"type":"bold"}]},{"type":"text","text":" moves an earlier version back into use. Nothing is deleted. "},{"type":"text","text":"Discard draft","marks":[{"type":"bold"}]},{"type":"text","text":" goes back to the live version."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"+ New format","marks":[{"type":"bold"}]},{"type":"text","text":" adds a format. It isn't offered to reporters until you publish it."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The formats to start with"}]},{"type":"paragraph","content":[{"type":"text","text":"Five formats come built in, each a description and a set of guardrails: Reader / Voicer (about 0:30 to 0:45, no actualities), Cut and Copy (0:45, one actuality), Wrap (about 0:45 to 1:00, one or two), Super Spot (2:00, one to three) and Feature (4:00, two to six). Anything else, such as a two-way or an interview, is a format you can add. Change the built-in ones like any other format."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-accept-in-bulk',
  p_tool_key => 'transcription',
  p_title => 'Accepting suggestions in bulk',
  p_summary => 'Accept every finding or clip waiting in a project, or in one source, at once instead of one by one.',
  p_screen_keys => array['sourcework.project', 'sourcework.source'],
  p_sort_order => 24,
  p_version_note => 'The Review tab''s two accept-all buttons',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When Analyze suggests a lot of findings, you do not have to decide on each one separately. Each accept-all button asks you to confirm first, because you are deciding on many things without reading each."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"On the project's Review tab"}]},{"type":"paragraph","content":[{"type":"text","text":"The panel at the top says how many findings and clips, from how many sources, are waiting. "},{"type":"text","text":"Accept all","marks":[{"type":"bold"}]},{"type":"text","text":" with the count accepts every waiting finding in the project. "},{"type":"text","text":"Accept all","marks":[{"type":"bold"}]},{"type":"text","text":" with the count of clips makes every waiting clip into an excerpt at the range Analyze proposed; each can still be trimmed or deleted in its source afterwards, and a clip that couldn't be accepted stays waiting, which the message says."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"In one source"}]},{"type":"paragraph","content":[{"type":"text","text":"On a source's Data points panel, with the "},{"type":"text","text":"To review","marks":[{"type":"bold"}]},{"type":"text","text":" filter showing and more than one finding waiting, "},{"type":"text","text":"Accept all","marks":[{"type":"bold"}]},{"type":"text","text":" accepts the findings waiting in that source only. Findings you have already decided on are left as they are."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Taking a decision back"}]},{"type":"paragraph","content":[{"type":"text","text":"Nothing is deleted by accepting. A finding can be rejected or put back for review afterwards, and an accepted clip is an ordinary excerpt you can delete."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-synthesis',
  p_tool_key => 'transcription',
  p_title => 'Synthesis',
  p_summary => 'Read what a project''s accepted findings establish for each research question, hear the evidence, and decide what to do with the patterns that emerge.',
  p_screen_keys => array['sourcework.synthesis'],
  p_sort_order => 20,
  p_version_note => 'When the tab appears, and the button''s labels',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthesis reads every finding you have accepted in a project and says what they establish about each of your research questions. It is a reading aid: nothing on this tab is evidence, and every statement opens onto the findings behind it. The tab appears once the project has an accepted finding, and its badge counts the findings accepted since the last run."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The top of the tab"}]},{"type":"paragraph","content":[{"type":"text","text":"The header says which version you are reading, when it was written and how many findings and sources it reads. "},{"type":"text","text":"Synthesize","marks":[{"type":"bold"}]},{"type":"text","text":" writes the first version; afterwards the button reads "},{"type":"text","text":"Update synthesis","marks":[{"type":"bold"}]},{"type":"text","text":" when findings have changed, or "},{"type":"text","text":"Synthesize again","marks":[{"type":"bold"}]},{"type":"text","text":". The version menu lists every earlier one; reading an old version is read-only. When a version is not the first, a line under the header says what changed since the previous run: new statements, removed ones, and statements whose certainty moved."}]},{"type":"paragraph","content":[{"type":"text","text":"Under it, a summary shows the whole answer at once: how many statements are established, contested and uncertain, and how many tensions, open points and patterns there are. A count in red means statements that no longer have an accepted finding behind them. The chips under the summary show only statements of one certainty."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Reading a statement"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each statement carries a certainty. Five dots show how many different sources it rests on, and "},{"type":"text","text":"One source's account","marks":[{"type":"bold"}]},{"type":"text","text":" marks a statement that rests on a single source."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Evidence","marks":[{"type":"bold"}]},{"type":"text","text":" on a statement to open the findings behind it beside the synthesis, or in a sheet on a phone. Play at a time plays that finding in place, and "},{"type":"text","text":"Open in source","marks":[{"type":"bold"}]},{"type":"text","text":" goes to the passage in the full recording or page."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Sections","marks":[{"type":"bold"}]},{"type":"text","text":" list moves between questions, patterns, conflicts and the moments worth hearing."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Patterns, and what is still open"}]},{"type":"paragraph","content":[{"type":"text","text":"Patterns across sources are things several people described separately that no question asked about. A pattern marked "},{"type":"text","text":"Passages only","marks":[{"type":"bold"}]},{"type":"text","text":" rests on moments the model found in the recordings, not on an accepted finding, so treat it as less firm. A pattern marked "},{"type":"text","text":"New","marks":[{"type":"bold"}]},{"type":"text","text":" was not in the previous run."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Track as a research question","marks":[{"type":"bold"}]},{"type":"text","text":" adds a question on the Setup tab, so the next Analyze listens for it. The pattern then reads "},{"type":"text","text":"Tracking","marks":[{"type":"bold"}]},{"type":"text","text":" and cannot be added twice."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dismiss","marks":[{"type":"bold"}]},{"type":"text","text":" hides a pattern. Dismissed patterns are listed under the patterns, with "},{"type":"text","text":"Restore","marks":[{"type":"bold"}]},{"type":"text","text":", and a new run does not offer them again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each open point has the same "},{"type":"text","text":"Track as a question","marks":[{"type":"bold"}]},{"type":"text","text":" action."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Choices you make here are saved as a new version marked as edited by a person, and a later run keeps them as they are."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-outline',
  p_tool_key => 'transcription',
  p_title => 'Outline a piece',
  p_summary => 'Plan a piece as beats before any narration is written, then write the outline out in place.',
  p_screen_keys => array['sourcework.piece'],
  p_sort_order => 22,
  p_version_note => 'The format is chosen at the top of the piece',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An outline plans a piece before any narration is written. It is a list of beats, each saying what that part of the story has to do, with your excerpts placed where they belong. You edit the outline, then write it out. Nothing is written for you until you ask."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Outline an empty piece"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open a new piece and choose "},{"type":"text","text":"Outline with AI","marks":[{"type":"bold"}]},{"type":"text","text":" on the "},{"type":"text","text":"Start your piece","marks":[{"type":"bold"}]},{"type":"text","text":" panel. The card says which format it is writing to; change it with "},{"type":"text","text":"Format","marks":[{"type":"bold"}]},{"type":"text","text":" at the top of the piece, where the format's guide is. Add a direction if you have one, and choose "},{"type":"text","text":"Outline the piece","marks":[{"type":"bold"}]},{"type":"text","text":". It can take a few minutes, because the model may check the transcripts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It works from the findings you have accepted, the project's synthesis if there is one, and every excerpt the project has. The first beat is the angle: the point of the piece in a sentence."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the project has no accepted excerpts yet, or findings and clips are still waiting, the panel says so and links to the Review tab."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The result is an ordinary version. Use History to go back, and edit it like any other piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Read a beat"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A beat takes no time, so the length at the top counts only narration and excerpts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What carries it","marks":[{"type":"bold"}]},{"type":"text","text":" opens the findings the beat rests on, with a link to listen where each was said. A finding you have since rejected is counted as no longer accepted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark to check","marks":[{"type":"bold"}]},{"type":"text","text":" flags a beat whose figure, name or attribution rests on one source or isn't settled. When the outline is written out, that sentence gets a bracketed check note instead of being stated as fact."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tape","marks":[{"type":"bold"}]},{"type":"text","text":" links to a stretch of a recording the outline thought worth your attention that is not an excerpt yet. Open it, and make an excerpt if you want it in the piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Change the outline"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Edit a beat's text directly. Use the + between blocks to add a narration block, an outline beat or an excerpt, and the ⋮ menu to move or remove one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The assistant can add and change beats too. Every change it makes is a version you can undo."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Write from outline"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece with beats shows "},{"type":"text","text":"Write from outline","marks":[{"type":"bold"}]},{"type":"text","text":". It writes each beat out as narration, in the same place, following the Writing guide editors maintain."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your excerpts, their trims, and anything you already wrote stay exactly as they are. The model cannot reorder the piece, add a clip or drop one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A beat the model leaves unwritten stays in the outline, and the page says how many. Undo returns you to the outline."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An outline and a draft are suggestions. Check every name, figure and attribution before you air anything."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An outline uses at most the 150 newest excerpts in a project."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interview text and your findings are sent to an outside service, as for transcription."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-project-overview',
  p_tool_key => 'transcription',
  p_title => 'A project at a glance',
  p_summary => 'See where a project stands, do the next step yourself or with AI, and find any source.',
  p_screen_keys => array['sourcework.project'],
  p_sort_order => 12,
  p_version_note => 'The strip is left out on a phone and once a piece exists; the tabs and the header as they are now',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A project opens on where it stands and what to do next. You can do every step yourself, ask AI to do any step, or hand it the rest."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The steps and the next step"}]},{"type":"paragraph","content":[{"type":"text","text":"The row of steps runs Sources, Analyze, Review, Synthesis, Piece. A finished step is a link back to its tab. Under it, one panel names the next step and gives you one button for it: "},{"type":"text","text":"Add the first source","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":" when sources are ready, "},{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":" with the count waiting, "},{"type":"text","text":"Open Review","marks":[{"type":"bold"}]},{"type":"text","text":" when nothing has been accepted yet, then "},{"type":"text","text":"Open Synthesis","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Start a piece","marks":[{"type":"bold"}]},{"type":"text","text":". The steps only report and suggest; you can use any tab at any time. Once the project has a piece, the strip and the panel are gone and the Pieces tab carries on. On a phone the row of steps is left out, since the tabs and the Review badge say the same, and the panel is one line with its button and the hand-over link side by side."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The title and background"}]},{"type":"paragraph","content":[{"type":"text","text":"The project's title and background sit at the top; the background is shown on every excerpt and search result from the project, so say what it was about. "},{"type":"text","text":"Add background","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Edit details","marks":[{"type":"bold"}]},{"type":"text","text":" under the title opens them for editing, as does "},{"type":"text","text":"Edit title and background","marks":[{"type":"bold"}]},{"type":"text","text":" in the ⋮ menu beside the title, which is the way in on a phone. The same menu holds "},{"type":"text","text":"Delete project…","marks":[{"type":"bold"}]},{"type":"text","text":", with a list of what goes and what stays."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tabs"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Notebook","marks":[{"type":"bold"}]},{"type":"text","text":" holds what you browse, in three sections. "},{"type":"text","text":"Sources","marks":[{"type":"bold"}]},{"type":"text","text":" lists the project's sources, "},{"type":"text","text":"Data points","marks":[{"type":"bold"}]},{"type":"text","text":" lists the findings you have accepted or rejected (filtered Accepted, Rejected or Both, each linking to its source), and "},{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" lists the excerpts made from them, with "},{"type":"text","text":"Export excerpts (zip)","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":" is where you decide on the findings and clips Analyze suggested, from every source at once. The number beside it is how many are waiting."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthesis","marks":[{"type":"bold"}]},{"type":"text","text":" appears once a finding has been accepted. "},{"type":"text","text":"Pieces","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Setup","marks":[{"type":"bold"}]},{"type":"text","text":", which holds the research questions and the pages the model consulted, complete the row."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Run the remaining steps with AI"}]},{"type":"paragraph","content":[{"type":"text","text":"The link under the button opens a dialog that runs the steps still to do, one after another, and hands control back where you choose: after Analyze, after Synthesis, after Outline, or after a first draft. It starts on Analyze, so the Review tab stays yours. Going past Analyze accepts every suggested finding and clip without your review, and the dialog says so before you start; they can be put back for review afterwards. Keep the page open while it runs. "},{"type":"text","text":"Stop after this step","marks":[{"type":"bold"}]},{"type":"text","text":" ends the run, and what finished is kept."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find a source"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each source has a bar showing how far it has come: processed, analyzed, reviewed. The word under it says which step it is on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filter sources","marks":[{"type":"bold"}]},{"type":"text","text":" searches titles. "},{"type":"text","text":"Show","marks":[{"type":"bold"}]},{"type":"text","text":" narrows the list to sources "},{"type":"text","text":"Not analyzed","marks":[{"type":"bold"}]},{"type":"text","text":" or that "},{"type":"text","text":"Need attention","marks":[{"type":"bold"}]},{"type":"text","text":", and "},{"type":"text","text":"Sort","marks":[{"type":"bold"}]},{"type":"text","text":" puts the newest first or sorts by title. The list shows 25 at a time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select a row to open the source. A source that failed to process says why under its title. The ⋮ menu at the end of the row opens the source or removes it from this project."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"+ Add source","marks":[{"type":"bold"}]},{"type":"text","text":" and, except when it is the panel's own button, "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":" sit with the filters above the source list."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hints that go away"}]},{"type":"paragraph","content":[{"type":"text","text":"Short how-to notes on some screens, such as how to select words into an excerpt, show a "},{"type":"text","text":"Got it","marks":[{"type":"bold"}]},{"type":"text","text":" button. Select it and that note stays hidden in this browser."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-browse-source-library',
  p_tool_key => 'transcription',
  p_title => 'Browse the Notebook',
  p_summary => 'Every recording, document and excerpt in Sourcework, whichever project it came from.',
  p_screen_keys => array['sourcework.sources', 'sourcework.source'],
  p_sort_order => 20,
  p_version_note => 'The Source Library became the Notebook''s Sources section',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Notebook","marks":[{"type":"bold"}]},{"type":"text","text":" tab on the Sourcework home lists everything you can reuse, independent of the projects that use it, in two sections."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sources"}]},{"type":"paragraph","content":[{"type":"text","text":"Every recording and document, as cards showing its kind, date, length or page count, and how many projects use it. The chips narrow the cards to "},{"type":"text","text":"Audio","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"PDF","marks":[{"type":"bold"}]},{"type":"text","text":", and typing in the search box narrows them by title as you type; Enter searches every transcript and excerpt instead, see "},{"type":"text","text":"Searching across projects and sources","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-search"}}]},{"type":"text","text":". Select a card to open the source on its own: the same player, transcript and excerpts a project shows, or the page viewer and text for a PDF, plus a "},{"type":"text","text":"Projects","marks":[{"type":"bold"}]},{"type":"text","text":" tab listing every project that uses it, with a filter once there are eight."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Excerpts"}]},{"type":"paragraph","content":[{"type":"text","text":"Every saved clip and passage. The title opens the source at that excerpt, and the project name opens the project it belongs to."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A source is the original recording or document. It is never edited; a project is the work that refers to it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To use a source in another story, add it from that project with "},{"type":"text","text":"+ Add source","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"Find existing","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A source opened from the Notebook can be deleted from its ⋮ menu, everywhere at once; one opened from a project can also be removed from just that project."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-15-sourcework-guides-realigned',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-15',
  p_title => 'Sourcework: the guides match the tool again',
  p_guide_slugs => array['sourcework-workflow-overview', 'sourcework-interview-to-script', 'sourcework-starting-a-project', 'sourcework-reference-another-source', 'sourcework-transcript-and-excerpts', 'sourcework-pieces', 'sourcework-research', 'sourcework-suggested-quotes', 'sourcework-research-prompts', 'sourcework-piece-formats', 'sourcework-accept-in-bulk', 'sourcework-synthesis', 'sourcework-outline', 'sourcework-project-overview', 'sourcework-browse-source-library'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every Sourcework guide was checked against the tool as it is today and brought up to date. The ones that still described the Source Library, the source switcher, Themes, suggested quotes on a theme or Draft with AI now describe the Notebook, the project's Review tab, the editors' Setup tab and the Analyze, Synthesis and Outline steps; a walkthrough from a recording to a script sits beside the overview. The dates on the Sourcework release notes since October 9 were also corrected to the day each change actually shipped."}]}]}$body$
);
